# 创建集群时指定企业项目
# 控制台 → 创建集群 → 高级配置 → 企业项目

# 通过 API 创建集群时指定
{
  "kind": "Cluster",
  "spec": {
    "enterpriseProjectId": "ep-xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx"
  }
}

# 集群创建后查看企业项目
kubectl get cluster <cluster-id> -o jsonpath='{.spec.enterpriseProjectId}'

